import {encodeState} from './state-codec.js';
export class OnlineSession{
 constructor(game,callbacks){this.game=game;this.callbacks=callbacks;this.role='';this.ready=false;this.remoteInput={};this.lastInput=0;this.lastSend=0;this.seq=0;this.started=false;this.socket=null;this.endpoint='';this.retry=0;
 const panel=this.panel=document.createElement('section');panel.className='online-panel';panel.setAttribute('aria-label','Jogar pela internet');panel.innerHTML='<h3>JOGAR PELA INTERNET</h3><p>Uma sala para duas pessoas. O criador escolhe o elenco e a fase; cada pessoa usa seus comandos do jogador 1. Conexão entre convidados, sem ranking.</p><button data-create>CRIAR SALA</button> <label>CÓDIGO DA SALA <input data-room maxlength="12" autocomplete="off" spellcheck="false" placeholder="12 caracteres"></label> <button data-join>ENTRAR</button> <button data-copy hidden>COPIAR CONVITE</button> <button data-leave hidden>SAIR DA SALA</button><p data-status role="status" aria-live="polite"></p>';
 (document.querySelector('.settings-launch')||document.querySelector('.game-shell')).after(panel);const css=document.createElement('style');css.textContent='.online-panel{margin:22px 0;padding:18px;border:1px solid #778d81;background:#102429;color:#f7eed8;font:14px/1.6 system-ui}.online-panel h3{font-size:18px}.online-panel button,.online-panel input{min-height:44px;font:inherit;padding:9px;background:#263c40;color:inherit;border:1px solid #acc5b5}.online-panel input{width:155px;text-transform:uppercase}.online-panel label{display:inline-flex;gap:8px;align-items:center;flex-wrap:wrap}.online-panel [hidden]{display:none!important}';document.head.append(css);
 panel.querySelector('[data-create]').onclick=()=>this.create();panel.querySelector('[data-join]').onclick=()=>this.join(panel.querySelector('[data-room]').value);panel.querySelector('[data-leave]').onclick=()=>this.leave();panel.querySelector('[data-copy]').onclick=async()=>{try{const url=new URL(location.href);url.search='';url.searchParams.set('room',this.code);await navigator.clipboard.writeText(url.href);this.status('Convite copiado. Envie para a outra pessoa.')}catch{this.status('Código da sala: '+this.code)}};
 this.configPromise=fetch('online-config.json',{cache:'no-store'}).then(r=>r.ok?r.json():{}).then(c=>{this.endpoint=c.endpoint||(/^localhost$|^127\.0\.0\.1$/.test(location.hostname)?'http://localhost:8790':'');if(!this.endpoint)this.status('O servidor online ainda não foi conectado. Os modos locais continuam disponíveis.')}).catch(()=>this.status('Servidor online indisponível. Tente novamente mais tarde.'));
 const invited=new URL(location.href).searchParams.get('room');if(invited)panel.querySelector('[data-room]').value=invited;
 this.ping=setInterval(()=>{if(this.socket?.readyState===1)this.socket.send('ping')},15000);
 }
 get active(){return !!this.role}get guest(){return this.role==='guest'}get host(){return this.role==='host'}
 status(text){this.panel.querySelector('[data-status]').textContent=text}
 async create(){this.callbacks.engage?.();await this.configPromise;if(!this.endpoint){this.status('O servidor online ainda não foi conectado.');return}this.leave(false);try{const response=await fetch(this.endpoint+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...this.callbacks.config(),game:this.game})});const room=await response.json();if(!response.ok)throw Error(room.error);this.code=room.code;this.token=room.token;this.role='host';this.status('Sala '+this.code+' criada. Compartilhe o convite; aguardando a outra pessoa.');this.connect()}catch(e){this.status('Não foi possível criar a sala. '+e.message)}}
 async join(code){this.callbacks.engage?.();await this.configPromise;code=code.trim().toUpperCase();if(!/^[A-F0-9]{12}$/.test(code)){this.status('Digite os 12 caracteres do convite.');return}if(!this.endpoint){this.status('O servidor online ainda não foi conectado.');return}this.leave(false);this.code=code;this.role='guest';this.status('Conectando à sala…');this.connect()}
 connect(){const url=this.endpoint.replace(/^http/,'ws')+'/rooms/'+this.code;const protocols=['brasa-v1'];if(this.host)protocols.push('host.'+this.token);const socket=this.socket=new WebSocket(url,protocols);this.panel.querySelector('[data-leave]').hidden=false;this.panel.querySelector('[data-copy]').hidden=false;this.panel.querySelector('[data-room]').value=this.code;
 socket.onopen=()=>{this.retry=0};socket.onmessage=e=>{if(e.data==='pong')return;let p;try{p=JSON.parse(e.data)}catch{return}if(p.type==='welcome'){if(p.config.game!==this.game){this.status('Este convite pertence ao outro jogo.');this.leave(false);return}this.config=p.config;this.callbacks.configured?.(p.config)}if(p.type==='presence'){this.ready=p.host&&p.guest;if(this.ready){this.status('Sala '+this.code+' · '+(this.host?'você é 1P':'você é 2P')+' · conectados');if(this.host&&!this.started){this.started=true;this.callbacks.start(this.config)}}else this.status('Sala '+this.code+' · aguardando a outra pessoa.')}if(p.type==='input'&&this.host){this.remoteInput=p.input;this.lastInput=performance.now()}if(p.type==='state'&&this.guest){try{this.callbacks.state(p.state,p.paused)}catch{this.status('O estado recebido era incompatível. Reabra a sala.');this.leave(false)}}if(p.type==='action'&&this.host)this.callbacks.action(p.kind);if(p.type==='finish'&&this.host)this.callbacks.finish?.(p.key);if(p.type==='control')this.callbacks.pause(p.action==='pause');if(p.type==='peer-left'){this.ready=false;this.remoteInput={};this.callbacks.pause(true);this.status('A outra pessoa desconectou. A partida está pausada. Aguarde ou saia da sala para jogar localmente.')}};
 socket.onerror=()=>this.status('Não foi possível conectar: confira o código, se a sala está cheia ou se expirou.');socket.onclose=()=>{if(this.socket!==socket||!this.active)return;this.ready=false;this.callbacks.pause(true);if(this.retry++<3){this.status('Conexão interrompida. Tentando reconectar…');setTimeout(()=>{if(this.active)this.connect()},1000*this.retry)}else{this.status('Conexão encerrada. Saia da sala e crie um novo convite.')}};
 }
 send(packet){if(this.socket?.readyState===1&&this.socket.bufferedAmount<180000)this.socket.send(JSON.stringify(packet))}
 input(input){const now=performance.now();if(this.guest&&now-this.lastSend>32){this.lastSend=now;this.send({type:'input',input,seq:++this.seq})}}
 action(kind){if(this.guest)this.send({type:'action',kind})}
 control(paused){this.send({type:'control',action:paused?'pause':'resume'})}
 publish(simulation,paused){const now=performance.now();if(this.host&&this.ready&&simulation&&now-this.lastSend>66){this.lastSend=now;this.send({type:'state',state:encodeState(simulation),paused,seq:++this.seq})}}
 remote(){return performance.now()-this.lastInput<600?this.remoteInput:{}}
 interpolate(simulation,dt){for(const p of [...simulation?.players||simulation?.fighters||[],...simulation?.enemies||[]])for(const key of ['x','lane','y'])if(Number.isFinite(p['net_'+key]))p[key]+=(p['net_'+key]-p[key])*(1-Math.exp(-24*dt))}
 leave(message=true){const old=this.socket;this.socket=null;this.role='';this.ready=false;this.started=false;this.remoteInput={};this.retry=0;old?.close();this.panel.querySelector('[data-leave]').hidden=true;this.panel.querySelector('[data-copy]').hidden=true;if(message){this.callbacks.pause(true);this.status('Sala encerrada neste aparelho. Você pode continuar no modo local.')}}
}
export function smoothSnapshot(previous,next){const old=new Map([...(previous?.players||previous?.fighters||[]),...(previous?.enemies||[])].map(p=>[(p.enemy?'enemy:':'player:')+p.index,p]));for(const actor of [...(next.players||next.fighters||[]),...(next.enemies||[])]){const before=old.get((actor.enemy?'enemy:':'player:')+actor.index);if(!before)continue;for(const key of ['x','lane','y'])if(Number.isFinite(actor[key])&&Number.isFinite(before[key])){actor['net_'+key]=actor[key];actor[key]=before[key]}}return next}
